    (folder/"approval_items.json").write_text(json.dumps({"scale":2.85,"status":"awaiting_user_selection","environment_modified":False,"items":[{"number":c[0],"title":c[1],"evidence":c[5],"proposal":c[6],"image":f"review_{c[0]:02d}.png","approved":None} for c in cases]},ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
    print(f"Review prepared: {len(cases)} approval items, all 12 sections, no environment edits.")

